{{ config(materialized='table') }}

with
quarantined as (
    select
        decision_id,
        external_deal_id,
        decision,
        conditions,
        actor,
        decided_at,
        violation_00,
        violation_01
    from {{ ref("investment__deal_decision_current__checked") }}
),
violations as (
    select
        'decision_id_not_null' as rule_name,
        decision_id,
        external_deal_id,
        decision,
        conditions,
        actor,
        decided_at
    from quarantined
    where violation_00

    union all

    select
        'external_deal_id_not_null' as rule_name,
        decision_id,
        external_deal_id,
        decision,
        conditions,
        actor,
        decided_at
    from quarantined
    where violation_01
)

select
    rule_name,
    decision_id,
    external_deal_id,
    decision,
    conditions,
    actor,
    decided_at
from violations
